import json,os,re,stat,subprocess,zipfile,tarfile,shlex,time
from pathlib import Path,PurePosixPath
from urllib.parse import urlsplit
R={"phase":"r105-pink-backup-review","read_only":True,"secrets_emitted":False,
   "extracted_files":0,"deleted_bytes":0,"network_requests":0}
LIMIT=16*1024*1024
MAX_CONFIG=256*1024
MAX_ENTRIES=1500
deadline=time.monotonic()+40
PROTECTED=("vivoapk-backend.service","jellyfin-pink.service","nginx.service","postgresql.service")
NAMES={"backend-auth.env","backend-runtime.env","native-media.env","backend.env",
       "secrets.env","mega.env","provider.env","vpn.env","wireguard.conf","wg0.conf",
       ".env","settings.env","config.json","settings.json","provider.json","mega.json"}
def state():
    out={}
    for u in PROTECTED:
        p=subprocess.run(["systemctl","show",u,"--property=ActiveState,MainPID","--no-pager"],capture_output=True,text=True,timeout=6)
        out[u]=p.stdout if p.returncode==0 else ""
    return out
def realdir(p):return p.is_dir() and not p.is_symlink() and p.resolve()==p
def scheme(v):
    try:
        p=urlsplit(v);return p.scheme.lower() if p.hostname else ""
    except (ValueError,TypeError):return ""
def scan_config(name,data):
    if len(data)>MAX_CONFIG:return
    try:s=data.decode("utf-8","strict")
    except UnicodeError:return
    R["config_files_examined"]+=1
    if re.search(r"(?im)^\s*\[Peer\]\s*$",s) and re.search(r"(?im)^\s*\[Interface\]\s*$",s):R["wireguard_configs"]+=1
    d={}
    if name.endswith(".json"):
        try:
            obj=json.loads(s)
            def walk(x,prefix="",depth=0):
                if depth>5:return
                if isinstance(x,dict):
                    for k,v in x.items():
                        if not isinstance(k,str):continue
                        key=(prefix+"_"+k).strip("_").upper()
                        if isinstance(v,str):d[key]=v
                        elif isinstance(v,dict):walk(v,key,depth+1)
            walk(obj)
        except (ValueError,RecursionError):pass
    else:
        for l in s.splitlines():
            if "=" not in l or l.lstrip().startswith("#"):continue
            k,v=l.removeprefix("export ").split("=",1);k=k.strip().upper()
            if not re.fullmatch(r"[A-Z_][A-Z0-9_]*",k):continue
            try:
                parts=shlex.split(v,comments=True)
                if len(parts)==1 and parts[0]:d[k]=parts[0]
            except ValueError:pass
    for k,v in d.items():
        if k.endswith("MEGA_OTT_API_TOKEN"):R["api_token_present"]=True
        if k.endswith("MEGA_OTT_API_BASE") and scheme(v)=="https":R["api_management_https_present"]=True
        if k in ("VPN_CONTROL_SOCKET","VPN_ENDPOINT","VPN_SERVER_PUBLIC_KEY"):R["legacy_gateway_fields"]+=1
        if re.search(r"(MEGA|XTREAM|UPSTREAM|PROVIDER|MEDIA|DNS|ORIGIN)",k):
            if re.search(r"(VPN|TUNNEL|TLS|HTTPS|SSL|PROXY)",k):R["provider_secure_transport_fields"]+=1
            if re.search(r"(DNS|ORIGIN|MEDIA_URL|STREAM_URL)",k) and scheme(v)=="https":R["provider_https_media_origin_fields"]+=1
def allowed(name):
    p=PurePosixPath(name)
    return not p.is_absolute() and ".." not in p.parts and p.name.lower() in NAMES
def examine_zip(path):
    R["backup_type"]="zip"
    with zipfile.ZipFile(path) as z:
        infos=z.infolist()
        if len(infos)>MAX_ENTRIES or sum(i.file_size for i in infos)>64*1024*1024:raise ValueError("archive_bound")
        for i in infos:
            if time.monotonic()>deadline:raise TimeoutError()
            R["entries_examined"]+=1
            if not i.is_dir() and not stat.S_ISLNK(i.external_attr>>16) and allowed(i.filename) and i.file_size<=MAX_CONFIG:
                with z.open(i) as f:scan_config(PurePosixPath(i.filename).name.lower(),f.read(MAX_CONFIG+1))
def examine_tar(path):
    R["backup_type"]="tar"
    total=0
    with tarfile.open(path,"r|*") as t:
        for i in t:
            R["entries_examined"]+=1;total+=i.size
            if time.monotonic()>deadline or R["entries_examined"]>MAX_ENTRIES or total>64*1024*1024:raise ValueError("archive_bound")
            if i.isfile() and allowed(i.name) and i.size<=MAX_CONFIG:
                f=t.extractfile(i)
                if f:
                    with f:scan_config(PurePosixPath(i.name).name.lower(),f.read(MAX_CONFIG+1))
def examine_dir(path):
    R["backup_type"]="directory"
    for root,dirs,files in os.walk(path,followlinks=False):
        dirs[:]=[d for d in dirs if not (Path(root)/d).is_symlink()]
        for name in files:
            if time.monotonic()>deadline or R["entries_examined"]>=MAX_ENTRIES:raise ValueError("directory_bound")
            R["entries_examined"]+=1
            p=Path(root)/name
            if p.is_symlink() or name.lower() not in NAMES:continue
            fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
            with os.fdopen(fd,"rb") as f:
                st=os.fstat(f.fileno())
                if stat.S_ISREG(st.st_mode) and st.st_size<=MAX_CONFIG:scan_config(name.lower(),f.read(MAX_CONFIG+1))
def run():
    before=state()
    candidates=set()
    for root in (Path("/srv/projects"),Path("/srv/backups"),Path("/var/backups"),
                 Path("/root/backups"),Path("/srv/projects/Vivoapk/backups"),
                 Path("/srv/projects/backups"),Path("/srv/projects/_retired")):
        if not realdir(root):continue
        for p in root.iterdir():
            if p==Path("/srv/projects/pink-iptv") or p.is_symlink():continue
            if re.search(r"pink[-_. ]?iptv|retiring[-_. ]?pink|pink[-_. ]?backup|backup[-_. ]?pink|pink[-_. ]?vpn",p.name,re.I) and (p.is_file() or realdir(p)):
                candidates.add(p)
    R.update(candidates=len(candidates),entries_examined=0,config_files_examined=0,wireguard_configs=0,
      provider_secure_transport_fields=0,provider_https_media_origin_fields=0,legacy_gateway_fields=0,
      api_token_present=False,api_management_https_present=False)
    if len(candidates)!=1:raise ValueError("candidate_count_changed")
    p=next(iter(candidates))
    d=subprocess.run(["du","-s","-x","-B1","--",str(p)],capture_output=True,text=True,timeout=8)
    if d.returncode:raise ValueError("size_unknown")
    R["allocated_bytes"]=int(d.stdout.split()[0])
    if not 0<R["allocated_bytes"]<=LIMIT:raise ValueError("size_bound")
    if p.is_dir():examine_dir(p)
    elif zipfile.is_zipfile(p):examine_zip(p)
    elif tarfile.is_tarfile(p):examine_tar(p)
    else:R["backup_type"]="unsupported_file";raise ValueError("format_unknown")
    R["protected_services_unchanged"]=before==state()
    R["protected_services_active"]=all("ActiveState=active" in v for v in before.values())
    R["status"]="checked"
try:run()
except Exception as exc:R.update(status="blocked",blocker=type(exc).__name__)
print(json.dumps(R,sort_keys=True),flush=True)
raise SystemExit(0 if R.get("status")=="checked" and R.get("protected_services_unchanged") and R.get("protected_services_active") else 1)
